:root {
  --bg: #191b2e;
  --surface: #262a44;
  --surface-alt: #313656;
  --text: #f5f3ff;
  --accent: #ffd166;
  color-scheme: dark;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  background:
    radial-gradient(circle at top left, rgba(255, 209, 102, 0.14), transparent 45%),
    radial-gradient(circle at bottom right, rgba(255, 209, 102, 0.08), transparent 40%),
    var(--bg);
}

.game-shell {
  width: 100%;
  max-width: 560px;
  background: var(--surface);
  border-radius: 20px;
  padding: 24px;
  box-shadow: 0 14px 40px rgba(0, 0, 0, 0.35);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

h1 {
  margin: 0;
  font-size: 2rem;
  letter-spacing: 0.03em;
  text-align: center;
  color: var(--accent);
  text-shadow: 0 0 12px rgba(255, 209, 102, 0.35);
}

.subtitle {
  margin: 8px 0 20px;
  text-align: center;
  opacity: 0.82;
}

.status-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 16px;
}

.moves {
  margin: 0;
  font-weight: 700;
  font-size: 1.1rem;
}

#move-count {
  display: inline-block;
  min-width: 2ch;
  padding: 4px 10px;
  text-align: center;
  background: var(--surface-alt);
  border-radius: 999px;
}

#new-game {
  background: var(--accent);
  color: #191b2e;
  border: none;
  border-radius: 999px;
  padding: 10px 18px;
  cursor: pointer;
  font-weight: 800;
  transition: transform 0.15s ease, box-shadow 0.15s ease, filter 0.15s ease;
  box-shadow: 0 6px 14px rgba(0, 0, 0, 0.25);
}

#new-game:hover {
  filter: brightness(1.05);
  transform: translateY(-2px);
  box-shadow: 0 10px 18px rgba(0, 0, 0, 0.3);
}

#new-game:active {
  transform: translateY(1px);
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.25);
}

#new-game:focus-visible,
.card:focus-visible {
  outline: 3px solid #ffffff;
  outline-offset: 3px;
}

.win-message {
  min-height: 1.5em;
  margin: 0 0 12px;
  text-align: center;
  font-weight: 800;
  color: var(--accent);
  opacity: 0;
  transform: translateY(-4px);
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.win-message.visible {
  opacity: 1;
  transform: translateY(0);
}

.game-board {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: clamp(10px, 2.5vw, 16px);
  max-width: 480px;
  margin: 0 auto;
}

.card {
  position: relative;
  aspect-ratio: 3 / 4;
  padding: 0;
  border: 0;
  border-radius: 14px;
  background: transparent;
  cursor: pointer;
  perspective: 800px;
}

.card-inner {
  position: absolute;
  inset: 0;
  transform-style: preserve-3d;
  transition: transform 0.45s cubic-bezier(0.2, 0.75, 0.25, 1);
}

.card.flipped .card-inner,
.card.matched .card-inner {
  transform: rotateY(180deg);
}

.card:not(.flipped):not(.matched):hover .card-inner {
  transform: scale(1.03);
}

.card:not(.flipped):not(.matched):active .card-inner {
  transform: scale(0.96);
}

.card-face {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  border-radius: 14px;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  box-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.08);
}

.card-back {
  background: var(--surface-alt);
  background-image: repeating-linear-gradient(
    45deg,
    rgba(255, 255, 255, 0.04) 0 8px,
    transparent 8px 16px
  );
  color: var(--text);
  font-size: 1.8rem;
}

.card-front {
  background: var(--card-color);
  transform: rotateY(180deg);
  box-shadow:
    inset 0 0 0 2px rgba(255, 255, 255, 0.18),
    0 8px 18px rgba(0, 0, 0, 0.25);
}

.card.matched .card-front {
  box-shadow:
    inset 0 0 0 3px var(--accent),
    0 0 16px rgba(255, 209, 102, 0.45);
  animation: pop 0.25s ease;
}

@keyframes pop {
  0% {
    transform: rotateY(180deg) scale(0.85);
  }
  100% {
    transform: rotateY(180deg) scale(1);
  }
}

@media (max-width: 480px) {
  body {
    padding: 12px 8px;
  }

  .game-shell {
    padding: 18px;
  }

  h1 {
    font-size: 1.7rem;
  }

  .subtitle {
    font-size: 1rem;
  }

  .status-bar {
    gap: 10px;
  }

  .game-board {
    gap: 8px;
  }
}

(() => {
  'use strict';

  const board = document.getElementById('game-board');
  const moveCount = document.getElementById('move-count');
  const winMessage = document.getElementById('win-message');
  const newGameBtn = document.getElementById('new-game');

  const pairColors = [
    { id: 0, name: 'red', color: '#ef476f' },
    { id: 1, name: 'orange', color: '#f78c6b' },
    { id: 2, name: 'yellow', color: '#ffd166' },
    { id: 3, name: 'green', color: '#06d6a0' },
    { id: 4, name: 'teal', color: '#118ab2' },
    { id: 5, name: 'blue', color: '#457b9d' },
    { id: 6, name: 'purple', color: '#b388eb' },
    { id: 7, name: 'pink', color: '#f15bb5' },
  ];

  let cards = [];
  let firstCard = null;
  let secondCard = null;
  let lockBoard = false;
  let moves = 0;
  let matchedPairs = 0;
  let timeoutId = null;

  function shuffle(array) {
    const arr = [...array];
    for (let i = arr.length - 1; i > 0; i -= 1) {
      const j = Math.floor(Math.random() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
  }

  function createCardData() {
    const deck = [];
    pairColors.forEach((pair) => {
      deck.push({ pairId: pair.id, name: pair.name, color: pair.color, matched: false });
      deck.push({ pairId: pair.id, name: pair.name, color: pair.color, matched: false });
    });
    return shuffle(deck);
  }

  function renderBoard() {
    if (timeoutId) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }

    board.innerHTML = '';
    cards = createCardData();
    firstCard = null;
    secondCard = null;
    lockBoard = false;
    moves = 0;
    matchedPairs = 0;
    updateMoveDisplay();
    winMessage.textContent = '';
    winMessage.classList.remove('visible');

    cards.forEach((card, index) => {
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'card';
      button.dataset.index = String(index);
      button.style.setProperty('--card-color', card.color);
      button.setAttribute('aria-label', `Card ${index + 1}: face down`);
      button.setAttribute('aria-pressed', 'false');

      const inner = document.createElement('span');
      inner.className = 'card-inner';

      const back = document.createElement('span');
      back.className = 'card-face card-back';
      back.setAttribute('aria-hidden', 'true');
      back.textContent = '?';

      const front = document.createElement('span');
      front.className = 'card-face card-front';
      front.setAttribute('aria-hidden', 'true');

      inner.appendChild(back);
      inner.appendChild(front);
      button.appendChild(inner);
      button.addEventListener('click', () => handleCardClick(button, card));
      board.appendChild(button);
    });
  }

  function updateMoveDisplay() {
    moveCount.textContent = String(moves);
  }

  function flipCard(button, card) {
    button.classList.add('flipped');
    button.setAttribute('aria-pressed', 'true');
    button.setAttribute('aria-label', `Card ${Number(button.dataset.index) + 1}: ${card.name}`);
  }

  function unflipCard(button) {
    button.classList.remove('flipped');
    button.setAttribute('aria-pressed', 'false');
    button.setAttribute('aria-label', `Card ${Number(button.dataset.index) + 1}: face down`);
  }

  function markMatched(button, card) {
    button.classList.add('matched');
    button.setAttribute('aria-pressed', 'true');
    button.setAttribute('aria-label', `Card ${Number(button.dataset.index) + 1}: ${card.name}, matched`);
  }

  function handleCardClick(button, card) {
    if (lockBoard) return;
    if (button.classList.contains('flipped') || card.matched) return;
    if (firstCard && firstCard.button === button) return;

    if (!firstCard) {
      firstCard = { button, card };
      flipCard(button, card);
      return;
    }

    secondCard = { button, card };
    flipCard(button, card);
    moves += 1;
    updateMoveDisplay();

    if (firstCard.card.pairId === secondCard.card.pairId) {
      firstCard.card.matched = true;
      secondCard.card.matched = true;
      markMatched(firstCard.button, firstCard.card);
      markMatched(secondCard.button, secondCard.card);
      matchedPairs += 1;
      firstCard = null;
      secondCard = null;

      if (matchedPairs === pairColors.length) {
        winMessage.textContent = `You won in ${moves} moves!`;
        winMessage.classList.add('visible');
      }
    } else {
      lockBoard = true;
      const first = firstCard;
      const second = secondCard;
      timeoutId = setTimeout(() => {
        unflipCard(first.button);
        unflipCard(second.button);
        firstCard = null;
        secondCard = null;
        lockBoard = false;
        timeoutId = null;
      }, 800);
      firstCard = null;
      secondCard = null;
    }
  }

  function startNewGame() {
    renderBoard();
    newGameBtn.focus();
  }

  newGameBtn.addEventListener('click', startNewGame);
  document.addEventListener('DOMContentLoaded', renderBoard);
})();
